// Synchronous protobuf codec for the ABIs generated by scripts/build.js (koilib format), with the
// same conventions as koilib: ADDRESS bytes are base58 strings, other bytes are base64url strings
// (Uint8Array/Buffer are also accepted when encoding) and 64-bit integers are decimal strings.
const protobuf = require("protobufjs");
const { utils } = require("koilib");

function toBytes(value, field) {
  if (value instanceof Uint8Array) return value;
  if (typeof value !== "string") throw new Error(`invalid bytes for ${field.name}: ${value}`);
  if (field.options && field.options["(koinos.btype)"] === "ADDRESS") return utils.decodeBase58(value);
  return utils.decodeBase64url(value);
}

function fromBytes(value, field) {
  const bytes = Uint8Array.from(value);
  if (field.options && field.options["(koinos.btype)"] === "ADDRESS") return utils.encodeBase58(bytes);
  return utils.encodeBase64url(bytes);
}

const INT64 = new Set(["int64", "uint64", "sint64", "fixed64", "sfixed64"]);

/** converts a JS object (koilib conventions) to the plain object protobufjs encodes */
function normalize(type, obj) {
  const out = {};
  for (const field of type.fieldsArray) {
    const value = obj[field.name];
    if (value === undefined || value === null) continue;
    const convert = (v) => {
      if (field.resolvedType instanceof protobuf.Type) return normalize(field.resolvedType, v);
      if (field.type === "bytes") return toBytes(v, field);
      if (INT64.has(field.type)) return typeof v === "bigint" ? v.toString() : String(v);
      if (field.type === "string" && typeof v === "bigint") return v.toString();
      return v;
    };
    out[field.name] = field.repeated ? value.map(convert) : convert(value);
  }
  return out;
}

/** converts a decoded protobufjs message to koilib conventions (defaults included) */
function denormalize(type, message) {
  const out = {};
  for (const field of type.fieldsArray) {
    const value = message[field.name];
    const convert = (v) => {
      if (field.resolvedType instanceof protobuf.Type) return v === null || v === undefined ? undefined : denormalize(field.resolvedType, v);
      if (field.resolvedType instanceof protobuf.Enum) return v;
      if (field.type === "bytes") return fromBytes(v || new Uint8Array(0), field);
      if (INT64.has(field.type)) return (v === undefined || v === null ? 0 : v).toString();
      return v;
    };
    if (field.repeated) out[field.name] = (value || []).map(convert);
    else out[field.name] = convert(value === undefined || value === null ? field.typeDefault : value);
  }
  return out;
}

class Codec {
  constructor(abi) {
    this.abi = abi;
    this.root = protobuf.Root.fromJSON(abi.types || abi.koilib_types);
    this.root.resolveAll();
  }

  type(name) {
    return this.root.lookupType(name);
  }

  encode(typeName, obj = {}) {
    const type = this.type(typeName);
    return type.encode(type.fromObject(normalize(type, obj))).finish();
  }

  decode(typeName, bytes) {
    const type = this.type(typeName);
    return denormalize(type, type.decode(bytes || new Uint8Array(0)));
  }

  method(name) {
    const method = this.abi.methods[name];
    if (!method) throw new Error(`unknown method ${name}`);
    return method;
  }
}

module.exports = { Codec };
